import java.io.*;
import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line1 = br.readLine();
        if (line1 == null || line1.trim().isEmpty()) {
            line1 = "null";
        }
        String[] parts = line1.trim().split("\\s+");

        String line2 = br.readLine();
        int insertVal = line2 == null ? 0 : Integer.parseInt(line2.trim());

        TreeNode root = buildTree(parts);
        root = insertIntoBST(root, insertVal);

        List<String> result = levelOrder(root);
        System.out.println(String.join(" ", result));
    }

    static TreeNode buildTree(String[] parts) {
        if (parts.length == 0 || "null".equals(parts[0])) {
            return null;
        }
        TreeNode root = new TreeNode(Integer.parseInt(parts[0]));
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        int i = 1;
        while (!q.isEmpty() && i < parts.length) {
            TreeNode node = q.poll();

            if (i < parts.length && !"null".equals(parts[i])) {
                node.left = new TreeNode(Integer.parseInt(parts[i]));
                q.offer(node.left);
            }
            i++;

            if (i < parts.length && !"null".equals(parts[i])) {
                node.right = new TreeNode(Integer.parseInt(parts[i]));
                q.offer(node.right);
            }
            i++;
        }
        return root;
    }

    static TreeNode insertIntoBST(TreeNode root, int val) {
        if (root == null) {
            return new TreeNode(val);
        }
        if (val < root.val) {
            root.left = insertIntoBST(root.left, val);
        } else {
            root.right = insertIntoBST(root.right, val);
        }
        return root;
    }

    static List<String> levelOrder(TreeNode root) {
        List<String> result = new ArrayList<>();
        if (root == null) {
            result.add("null");
            return result;
        }
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        while (!q.isEmpty()) {
            TreeNode node = q.poll();
            if (node == null) {
                result.add("null");
                q.offer(null);
                q.offer(null);
            } else {
                result.add(String.valueOf(node.val));
                q.offer(node.left);
                q.offer(node.right);
            }
        }

        int i = result.size() - 1;
        while (i >= 0 && "null".equals(result.get(i))) {
            result.remove(i);
            i--;
        }

        return result;
    }
}
